import { IdCard } from "lucide-react";
import { FormEvent, useState } from "react";
import { executeDynamicMutation } from "../../api/lookups";
import { AutoDismissAlert } from "../../components/ui/AutoDismissAlert";
import { Input } from "../../components/ui/Input";
import { useAuth } from "../../state/AuthContext";
import type { LucideIcon } from "lucide-react";

// P_VAL1S1 : BRAND_CODE (blank on insert -> autogenerated in Oracle)
// P_VAL1S2 : COMPANY_CODE
// P_VAL1S3 : BRAND_NAME
// P_VAL1S4 : USER_ID
const PURCHASE_SALE_MSE_PRODBRAND = "PURCHASE_SALE_MSE_PRODBRAND";

export type TProductBrand = {
  brand_code?: string;
  brand_name?: string;
  user_id?: string;
  user_dt?: string;
};

type FormMode = "add" | "edit" | "view";

type Props = {
  mode: FormMode;
  existingData?: Partial<TProductBrand>;
  onClose: (shouldRefetch?: boolean) => void;
  onSavingChange?: (saving: boolean) => void;
};

const EMPTY: TProductBrand = {
  brand_code: "",
  brand_name: "",
  user_id: "",
  user_dt: "",
};

/* ─────────────────────────────────────────────────────────────
   SectionPanel — EXACT Freight structure (from WMS)
   ───────────────────────────────────────────────────────────── */
function SectionPanel({
  title,
  icon: Icon,
  children,
}: {
  title: string;
  icon: LucideIcon;
  children: React.ReactNode;
}) {
  return (
    <section className="freight-panel overflow-hidden rounded-md border bg-background shadow-sm">
      <div className="freight-panel-title flex items-center justify-between gap-2 border-b bg-muted/35 px-3 py-2">
        <div className="flex min-w-0 items-center gap-2">
          <span className="freight-section-icon">
            <Icon size={16} />
          </span>
          <div className="min-w-0">
            <h3 className="m-0 truncate text-[11px] font-semibold text-foreground">{title}</h3>
          </div>
        </div>
      </div>
      <div className="freight-panel-body p-3">{children}</div>
    </section>
  );
}

/* ─────────────────────────────────────────────────────────────
   Field — matches WmsMasterForm / Freight label styling
   ───────────────────────────────────────────────────────────── */
function Field({
  label,
  required,
  children,
  className,
}: {
  label: string;
  required?: boolean;
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <label className={`freight-field-label group flex flex-col gap-0.5 ${className ?? ""}`}>
      <span className="text-[11px] font-medium text-muted-foreground group-focus-within:text-primary transition-colors">
        {label}
        {required && <strong className="text-destructive ml-0.5 font-bold"> *</strong>}
      </span>
      {children}
    </label>
  );
}

export function AddProductBrandForm({ mode, existingData, onClose, onSavingChange }: Props) {
  const { user } = useAuth();
  const readonly = mode === "view";
  const isEdit = mode === "edit";
  const companyCode = user?.company_code ?? "";

  const [form, setForm] = useState<TProductBrand>(() => ({ ...EMPTY, ...existingData }));
  const [errors, setErrors] = useState<Partial<Record<keyof TProductBrand, string>>>({});
  const [apiError, setApiError] = useState("");

  const setField = (field: keyof TProductBrand, value: string) =>
    setForm((prev) => ({ ...prev, [field]: value }));

  const validate = (): boolean => {
    const next: Partial<Record<keyof TProductBrand, string>> = {};
    if (!form.brand_name?.trim()) next.brand_name = "Brand Name is required";
    setErrors(next);
    return Object.keys(next).length === 0;
  };

  const handleSubmit = async (event: FormEvent) => {
    event.preventDefault();
    if (readonly) return;
    if (!validate()) return;

    onSavingChange?.(true);
    setApiError("");
    try {
      await executeDynamicMutation({
        parameter: PURCHASE_SALE_MSE_PRODBRAND,
        loginid: user?.loginid ?? "ADMIN",
        // blank on add -> Oracle autogenerates; existing code on edit
        val1s1: isEdit ? form.brand_code ?? "" : "",
        val1s2: companyCode,
        val1s3: form.brand_name?.trim() ?? "",
        val1s4: user?.loginid ?? "ADMIN",
      });

      onClose(true);
    } catch (error) {
      setApiError(error instanceof Error ? error.message : "Unable to save product brand record");
    } finally {
      onSavingChange?.(false);
    }
  };

  return (
    <form className="grid content-start gap-4" id="brand-master-form" onSubmit={handleSubmit}>
      <AutoDismissAlert
        notice={apiError ? { type: "error", message: apiError } : null}
        onClose={() => setApiError("")}
      />

      {/* ── Code badge (move to the parent header next to "Draft" if you prefer) ── */}
      <div>
{/* <span className="inline-flex items-center gap-1 rounded border border-blue-200 bg-blue-50 px-2 py-0 text-[10.5px] leading-tight font-medium text-[#00378C]">
  Brand Code:
  <strong className="font-semibold">
    {mode === "add" ? "Auto-generated" : String(existingData?.brand_code ?? "")}
  </strong>
</span> */}
      </div>

      <SectionPanel title="Basic Information" icon={IdCard}>
        <div className="grid grid-cols-1 gap-3">
          <Field label="Brand Name" required>
            <Input
              disabled={readonly}
              value={form.brand_name ?? ""}
              onChange={(e) => setField("brand_name", e.target.value)}
              placeholder="e.g. Samsung"
              className={errors.brand_name ? "border-destructive focus-visible:ring-destructive" : ""}
            />
            {errors.brand_name && (
              <span className="mt-0.5 text-[10px] font-medium text-destructive">{errors.brand_name}</span>
            )}
          </Field>
        </div>
      </SectionPanel>
    </form>
  );
}